        DuaLine(788800L, "مفتونين انا نسالك حبك وحب من يحبك وحب عمل يقربنا", "tried. We ask You for Your love, the love of those who love You, and the love of deeds that bring us close"),
        DuaLine(800160L, "الى حبك يا ذا الجلال والاكرام", "to Your love, O Possessor of Majesty and Honour."),
        DuaLine(805760L, "يا حي يا قيوم", "O Ever-Living, O Sustainer,"),
        DuaLine(810000L, "برحمتك نستغيث", "by Your mercy we seek help."),
        DuaLine(814040L, "اصلح لنا شاننا كله ولا تكلنا الى انفسنا", "Set right all our affairs and do not leave us to ourselves"),
        DuaLine(820399L, "طرفه عين ولا اقل من ذلك اللهم انا نسالك", "for the blink of an eye or less. O Allah, we ask You"),
