        DuaLine(832839L, "وخير النجاح", "the best of success,"),
        DuaLine(835639L, "وخير العمل وخير الثواب", "the best of deeds and the best of rewards,"),
        DuaLine(840120L, "وخير الحياه", "the best of life"),
        DuaLine(843079L, "وخير الممات", "and the best of death."),
