        DuaLine(855680L, "وتقبل صلاتنا", "accept our prayers"),
        DuaLine(858519L, "واغفر خطيئاتنا", "and forgive our mistakes."),
        DuaLine(862600L, "ونسالك الدرجات العلى من الجنه", "We ask You for the highest ranks in Paradise."),
        DuaLine(867959L, "اللهم انا نسالك فواتح الخير", "O Allah, we ask You for the beginnings of good,"),
        DuaLine(874040L, "وخواتمه وجوامعه", "its endings and its totality,"),
