        DuaLine(929680L, "الموحدين اللهم اعد المسجد الاقصى", "servants who believe in Your oneness. O Allah, return Al-Aqsa Mosque"),
        DuaLine(936040L, "الى رحاب المسلمين", "to the courtyards of the Muslims."),
        DuaLine(939720L, "اللهم وطهره من اليهود الغاصبين", "O Allah, cleanse it of the usurping Jews."),
        DuaLine(946079L, "اللهم عليك بهم فانهم لا يعجزونك", "O Allah, take them to account, for they cannot escape You,"),
        DuaLine(952399L, "يا قوي يا عزيز", "O Strong, O Mighty."),
        DuaLine(956360L, "اللهم منزل الكتاب", "O Allah, Revealer of the Book,"),
        DuaLine(960800L, "مجري السحاب", "Driver of the clouds,"),
        DuaLine(963720L, "هازم الاحزاب", "Defeater of the factions,"),
        DuaLine(967000L, "سريع الحساب", "Swift in reckoning,"),
        DuaLine(970680L, "اهزمهم وزلزلهم يا قوي يا عزيز", "defeat them and shake them, O Strong, O Mighty."),
        DuaLine(977000L, "ربنا تقبل منا", "Our Lord, accept from us;"),
        DuaLine(981319L, "انك انت السميع العليم", "indeed You are the All-Hearing, the All-Knowing,"),
        DuaLine(986440L, "وتب علينا", "and accept our repentance;"),
        DuaLine(989800L, "انك انت التواب الرحيم", "indeed You are the Accepter of repentance, the Merciful."),
        DuaLine(995759L, "اللهم انا نعوذ برضاك من سخطك وبمعافاتك", "O Allah, we seek refuge in Your pleasure from Your anger, and in Your pardon"),
        DuaLine(1002680L, "من عقوبتك", "from Your punishment,"),
        DuaLine(1004600L, "وبك منك لا نحصي ثناء", "and in You from You. We cannot count praise"),
        DuaLine(1008519L, "عليك انت كما اثنيت على نفسك وصل اللهم", "of You; You are as You have praised Yourself. And send blessings, O Allah,"),
        DuaLine(1014519L, "على نبينا محمد", "upon our Prophet Muhammad,"),
        DuaLine(1018480L, "وعلى اله وصحبه والتابعين", "and upon his family, companions and those who follow them."),
    )
}
